import csv, json

# --- independent re-implementation from scratch ---
rows=list(csv.DictReader(open('dissertation_section_log.csv')))
parts={r['part_id']:r for r in csv.DictReader(open('part_plan.csv'))}
tpls={r['template_id']:r for r in csv.DictReader(open('template_profiles.csv'))}

latest={}
for r in rows:
    s=r['section_id']
    if s not in latest or int(r['revision'])>int(latest[s]['revision']): latest[s]=r
A=list(latest.values())

ACCEPT={"Times New Roman","TimesNewRomanPSMT","Times New Roman PS MT Std"}
BE=3.0; REQ=18.0; TOL=0.05
WAIVER={"SEC-AN-01":"FONT","SEC-LOF":"TYPE_AREA","SEC-CH07":"CAPTION"}  # W-2 expired -> omitted
ORDER=["MARGIN_NONCOMPLIANT","TYPE_AREA_INVALID","LEADING_NONCOMPLIANT","FONT_NONCOMPLIANT","HEADING_STYLE_INVALID","CAPTION_MISSING","NUMBERING_INVALID"]

def audit(r):
    pid=r['part_id']; tpl=tpls[parts[pid]['template_id']]
    f=set()
    # §2
    if float(r['margin_top_cm'])<float(tpl['min_top_bottom_cm'])-1e-9: f.add("MARGIN_NONCOMPLIANT")
    if float(r['margin_bottom_cm'])<float(tpl['min_top_bottom_cm'])-1e-9: f.add("MARGIN_NONCOMPLIANT")
    if float(r['margin_inner_cm'])<BE-1e-9: f.add("MARGIN_NONCOMPLIANT")
    # §3
    pw=21.0 if r['orientation']=='portrait' else 29.7
    outer=round(pw-float(r['margin_inner_cm'])-float(r['text_block_width_cm']),2)
    ta=outer<float(tpl['min_outer_cm'])-1e-9
    if r['section_type']=='annex' and r['orientation']=='landscape' and r['widest_table_cm']:
        thr=round(29.7-BE-float(tpl['min_outer_cm']),2)
        if round(float(r['widest_table_cm']),2)>thr+1e-9: ta=False
    if ta and WAIVER.get(r['section_id'])=="TYPE_AREA": ta=False
    if ta: f.add("TYPE_AREA_INVALID")
    # §4
    lv=float(r['leading_value'])
    conv=round(lv/0.35,6) if r['leading_unit']=='mm' else round(lv,6)
    if abs(conv-REQ)>TOL+1e-9: f.add("LEADING_NONCOMPLIANT")
    # §5
    fr=[]
    if r['body_font_name'] not in ACCEPT: fr.append('name')
    if abs(float(r['body_font_size_pt'])-12.0)>1e-9: fr.append('size')
    if WAIVER.get(r['section_id'])=="FONT":  # clears identifier only; size still checked
        fr=['size'] if abs(float(r['body_font_size_pt'])-12.0)>1e-9 else []
    if fr: f.add("FONT_NONCOMPLIANT")
    # §6
    hr=[]
    if r['heading_font_name'] not in ACCEPT: hr.append('name')
    step=round(float(r['heading_font_size_pt'])-float(r['body_font_size_pt']),6)
    if step<float(tpl['min_heading_step_pt'])-1e-9: hr.append('step')
    if hr: f.add("HEADING_STYLE_INVALID")
    # §7
    if int(r['caption_count'])<int(r['float_count']) and WAIVER.get(r['section_id'])!="CAPTION":
        f.add("CAPTION_MISSING")
    # §8
    if r['page_number_style']!=parts[pid]['numbering']: f.add("NUMBERING_INVALID")
    return f

mine={}
for r in A:
    mine[r['section_id']]=(r['part_id'],parts[r['part_id']]['template_id'],audit(r))

# compare to formatting_audit.csv
deliv={}
for row in csv.DictReader(open('/app/formatting_audit.csv')):
    deliv[row['section_id']]=(row['part_id'],row['template_id'],row['finding'].split('|') if row['finding']!='none' else set())

ok=True
for sid in mine:
    mp,mt,mf=mine[sid]
    dp,dt,df=deliv[sid]
    mf_s=set(mf)
    if mp!=dp or mt!=dt:
        print('PART/TPL MISMATCH',sid,mp,mt,'vs',dp,dt); ok=False
    if mf_s!=df:
        print('FINDING MISMATCH',sid,'mine=',mf_s,'deliv=',df); ok=False
print('ALL SECTIONS MATCH:' , ok)

# counts vs results.json
R=json.load(open('/app/results.json'))
def cnt(code): return sum(1 for s,f in mine.values() if code in f)
flagged=[s for s,f in mine.values() if f]
print('section_count',len(mine),R['section_count'],len(mine)==R['section_count'])
print('flagged',len(flagged),R['flagged_section_count'])
print('clean',len(mine)-len(flagged),R['clean_section_count'])
print('finding_total',sum(len(f) for _,f in mine.values()),R['finding_total'])
for code,k in [("MARGIN_NONCOMPLIANT","margin_count"),("TYPE_AREA_INVALID","type_area_count"),("LEADING_NONCOMPLIANT","leading_count"),("FONT_NONCOMPLIANT","font_count"),("HEADING_STYLE_INVALID","heading_count"),("CAPTION_MISSING","caption_missing_count"),("NUMBERING_INVALID","numbering_count")]:
    print(k,cnt(code),R[k], cnt(code)==R[k])
arch=sum(1 for s,f in mine.values() if f and parts[s if False else None] if False else 0)  # placeholder
fa=sum(1 for s,p,t in [(s,)+v for s,v in mine.items()] if t=='TPL-ARCHIVE' and mine[s][2])
fr2=sum(1 for s,v in mine.items() if v[1]=='TPL-READING' and v[2])
print('flagged_archive',fa,R['flagged_archive_sections'])
print('flagged_reading',fr2,R['flagged_reading_sections'])
EOF

